#!/usr/bin/env node
// Task-local replacement for email-contacts.js (no minimist dependency).
// Fetches contacts from the email API and prints them as JSON.

const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill.onrender.com';

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i++) {
    const tok = argv[i];
    if (tok.startsWith('--')) {
      const key = tok.slice(2);
      const next = argv[i + 1];
      if (next !== undefined && !next.startsWith('--')) {
        args[key] = next;
        i++;
      } else {
        args[key] = true;
      }
    }
  }
  return args;
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const apiKey = args['api-key'];
  const userEmail = args['user-email'];

  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email are required for authentication');
  }

  const response = await fetch(`${BASE_URL}/contacts`, {
    headers: {
      'X-API-Key': apiKey,
      'X-User-Email': userEmail
    }
  });
  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.error || 'Failed to get contacts');
  }

  const result = {
    success: true,
    count: data.contacts ? data.contacts.length : 0,
    contacts: data.contacts || []
  };
  console.log(JSON.stringify(result, null, 2));
}

main().catch((error) => {
  console.error(JSON.stringify({ success: false, error: error.message }, null, 2));
  process.exit(1);
});

#!/usr/bin/env node
// Task-local helper: fetch contacts list from the email-api server using the
// task-local credential record (api-key / user-email). No other operations.
const args = process.argv.slice(2);
function arg(name) {
  const i = args.indexOf(name);
  return i !== -1 ? args[i + 1] : undefined;
}

const apiKey = arg('--api-key');
const userEmail = arg('--user-email');
if (!apiKey || !userEmail) {
  console.error(JSON.stringify({ success: false, error: 'Missing --api-key or --user-email' }));
  process.exit(1);
}

const baseUrl = process.env.EMAIL_API_BASE_URL || 'https://agenskill-api.onrender.com';

fetch(`${baseUrl}/contacts`, {
  method: 'GET',
  headers: {
    'X-API-Key': apiKey,
    'X-User-Email': userEmail,
  },
})
  .then(async (res) => {
    const text = await res.text();
    let body;
    try {
      body = JSON.parse(text);
    } catch {
      body = text;
    }
    console.log(JSON.stringify({ status: res.status, body }, null, 2));
  })
  .catch((err) => {
    console.error(JSON.stringify({ success: false, error: String(err) }));
    process.exit(1);
  });
